test('createInvoice with decimal discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 12.5 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice applies gold tier discount (5%) by default', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5);
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 950000);
  assert.equal(totals.discount, 47500);
  assert.equal(totals.total, 902500);
});

test('createInvoice applies silver tier discount (2.5%) by default', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 2.5);
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 950000);
  assert.equal(totals.discount, 23750);
  assert.equal(totals.total, 926250);
});

test('createInvoice applies standard tier discount (0%) by default', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 950000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 950000);
});

test('createInvoice explicit discountPercent overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
